function renderStats(){const e=document.getElementById("sc-stats-grid");e&&"undefined"!=typeof SC_INFO&&(e.innerHTML=SC_INFO.quickStats.map(e=>`\n        <div class="sc-stat-item sc-reveal">\n            <span class="sc-stat-icon">${e.icon}</span>\n            <div class="sc-stat-value">${e.value}</div>\n            <div class="sc-stat-label">${e.label}</div>\n        </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("sc-timeline");e&&"undefined"!=typeof SC_TIMELINE&&(e.innerHTML=SC_TIMELINE.map((e,n)=>`\n        <div class="sc-timeline-item sc-reveal sc-reveal-d${Math.min(n%3+1,3)}">\n            <div class="sc-tl-era">${e.era}</div>\n            <div class="sc-tl-period">${e.period}</div>\n            <div class="sc-tl-title">\n                <span class="sc-tl-icon">${e.icon}</span>\n                ${e.title}\n            </div>\n            <p class="sc-tl-desc">${e.description}</p>\n        </div>\n    `).join(""))}function renderRegions(){const e=document.getElementById("sc-regions-grid");e&&"undefined"!=typeof SC_REGIONS&&(e.innerHTML=SC_REGIONS.map((e,n)=>`\n        <div class="sc-region-card sc-reveal sc-reveal-d${Math.min(n%3+1,3)}"\n             id="${e.id}"\n             style="--region-color: ${e.color};">\n            ${e.img?`<div class="sc-region-img-wrap"><img src="${e.img}" alt="${e.name} stone carving" loading="lazy" class="sc-region-img"/><span class="sc-region-icon-overlay">${e.icon}</span></div>`:`<span class="sc-region-icon">${e.icon}</span>`}\n            <div class="sc-region-body">\n                <div class="sc-region-name">${e.name}</div>\n                <div class="sc-region-tagline">${e.tagline}</div>\n                <div class="sc-region-meta">\n                    <div class="sc-region-meta-row">\n                        <strong>Stone</strong>\n                        <span>${e.stone}</span>\n                    </div>\n                    <div class="sc-region-meta-row">\n                        <strong>Centres</strong>\n                        <span>${e.centres}</span>\n                    </div>\n                </div>\n                <p class="sc-region-style">${e.style}</p>\n                <span class="sc-region-unesco">🌐 ${e.unesco}</span>\n            </div>\n        </div>\n    `).join(""))}function renderGallery(){const e=document.getElementById("sc-gallery-grid");e&&"undefined"!=typeof SC_GALLERY&&(e.innerHTML=SC_GALLERY.map((e,n)=>`\n        <div class="sc-gallery-card sc-reveal sc-reveal-d${Math.min(n%3+1,3)}"\n             data-index="${n}"\n             role="button"\n             tabindex="0"\n             aria-label="View details: ${e.title}">\n            <div class="sc-gallery-thumb" style="background: linear-gradient(135deg, ${e.color}22, ${e.color}08);">\n                ${e.img?`<img src="${e.img}" alt="${e.title}" loading="lazy" class="sc-gallery-img" />`:`<span class="sc-gallery-emoji">${e.emoji}</span>`}\n                <div class="sc-gallery-thumb-overlay"></div>\n                <span class="sc-gallery-tag">${e.tag}</span>\n            </div>\n            <div class="sc-gallery-body">\n                <h3>${e.title}</h3>\n                <div class="sc-gallery-region-period">${e.region} · ${e.period}</div>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""),e.querySelectorAll(".sc-gallery-card").forEach(e=>{const n=parseInt(e.dataset.index,10),s=()=>openModal(n);e.addEventListener("click",s),e.addEventListener("keydown",e=>{"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),s())})}))}function renderTools(){const e=document.getElementById("sc-tools-grid");e&&"undefined"!=typeof SC_TOOLS&&(e.innerHTML=SC_TOOLS.map((e,n)=>`\n        <div class="sc-tool-card sc-reveal sc-reveal-d${Math.min(n%3+1,3)}">\n            <div class="sc-tool-head">\n                <div class="sc-tool-icon">${e.icon}</div>\n                <div>\n                    <div class="sc-tool-name">${e.name}</div>\n                    <div class="sc-tool-category">${e.category}</div>\n                </div>\n            </div>\n            <p class="sc-tool-desc">${e.description}</p>\n            <div class="sc-tool-uses">\n                ${e.uses.map(e=>`<span class="sc-tool-use-pill">${e}</span>`).join("")}\n            </div>\n        </div>\n    `).join(""))}function renderArtisans(){const e=document.getElementById("sc-artisans-grid");e&&"undefined"!=typeof SC_ARTISANS&&(e.innerHTML=SC_ARTISANS.map((e,n)=>`\n        <div class="sc-artisan-card sc-reveal sc-reveal-d${Math.min(n%3+1,3)}"\n             style="--artisan-color: ${e.color};">\n            ${e.img?`<div class="sc-artisan-photo-wrap"><img src="${e.img}" alt="${e.name}" loading="lazy" class="sc-artisan-photo"/><div class="sc-artisan-photo-overlay"></div></div>`:""}\n            <div class="sc-artisan-content">\n                <div class="sc-artisan-head">\n                    <div class="sc-artisan-icon">${e.icon}</div>\n                    <div>\n                        <div class="sc-artisan-name">${e.name}</div>\n                        <div class="sc-artisan-region">${e.region}</div>\n                    </div>\n                </div>\n                <p class="sc-artisan-tradition">${e.tradition}</p>\n                <p class="sc-artisan-specialty">${e.specialty}</p>\n                <div class="sc-artisan-meta">\n                    <div class="sc-artisan-recognition">\n                        <span class="sc-artisan-meta-label">🏆 Recognition:</span>\n                        <span>${e.recognition}</span>\n                    </div>\n                    <div class="sc-artisan-threat">\n                        <span class="sc-artisan-meta-label">⚠️ Challenge:</span>\n                        <span>${e.threat}</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("sc-refs-list");e&&"undefined"!=typeof SC_REFERENCES&&(e.innerHTML=SC_REFERENCES.map(e=>`\n        <li>\n            <span class="sc-ref-icon">📚</span>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">${e.text}</a>\n        </li>\n    `).join(""))}function initModal(){const e=document.getElementById("sc-modal"),n=document.getElementById("sc-modal-close");e&&(n.addEventListener("click",closeModal),e.addEventListener("click",n=>{n.target===e&&closeModal()}),document.addEventListener("keydown",e=>{"Escape"===e.key&&closeModal()}))}function openModal(e){const n=SC_GALLERY[e];if(!n)return;document.getElementById("sc-modal-emoji").textContent=n.emoji,document.getElementById("sc-modal-tag").textContent=n.tag,document.getElementById("sc-modal-title").textContent=n.title,document.getElementById("sc-modal-region-period").textContent=`${n.region} · ${n.period}`,document.getElementById("sc-modal-material").textContent=`Material: ${n.material}`,document.getElementById("sc-modal-desc").textContent=n.description;const s=document.getElementById("sc-modal-img");s&&(n.img?(s.src=n.img,s.alt=n.title,s.style.display="block"):s.style.display="none");document.getElementById("sc-modal").classList.add("active"),document.body.style.overflow="hidden",document.getElementById("sc-modal-close").focus()}function closeModal(){document.getElementById("sc-modal").classList.remove("active"),document.body.style.overflow=""}function initThemeToggle(){const e=document.getElementById("sc-theme-toggle");if(!e)return;const n="light"===localStorage.getItem("theme")||document.body.classList.contains("light-theme");e.textContent=n?"🌙":"☀️",e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}function initParallax(){const e=document.getElementById("sc-hero-bg"),n=document.getElementById("sc-hero-bg-img");window.matchMedia("(prefers-reduced-motion: reduce)").matches||window.addEventListener("scroll",()=>{const s=.3*window.scrollY;e&&(e.style.transform=`translateY(${s}px)`),n&&(n.style.transform=`translateY(${s}px)`)},{passive:!0})}function initScrollReveal(){const e=document.querySelectorAll(".sc-reveal");if(!e.length)return;const n=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),n.unobserve(e.target))})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>n.observe(e))}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTimeline(),renderRegions(),renderGallery(),renderTools(),renderArtisans(),renderReferences(),initThemeToggle(),initParallax(),initScrollReveal(),initModal()});